package cn.zhuatech.esg.controller; import cn.zhuatech.esg.common.ApiResponse; import cn.zhuatech.esg.dto.EsgDto.*; import cn.zhuatech.esg.service.EsgService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('DATA_OWNER','ADMIN')") public class DataOwnerController {private final EsgService service;public DataOwnerController(EsgService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}}
